def longest_subarray(nums):
    n = len(nums)
    best = 0
    for i in range(n):
        zeros = 0
        for j in range(i, n):
            if nums[j] == 0:
                zeros += 1
            if zeros <= 1:                          # recheck the whole subarray's zero count
                best = max(best, j - i + 1 - 1)
    return best

