def longest_subarray(nums):
    left, zeros, best = 0, 0, 0
    for right in range(len(nums)):
        if nums[right] == 0:
            zeros += 1
        while zeros > 1:                      # shrink until at most one zero remains
            if nums[left] == 0:
                zeros -= 1
            left += 1
        best = max(best, right - left + 1 - 1)  # minus 1 for the mandatory deletion
    return best

